// Copyright (c) 2026 Roshan. All rights reserved.// Proprietary license — see LICENSE file for details.package com.roshan.persona.productivity.alarmimport timber.log.Timberimport android.app.Notificationimport android.app.NotificationChannelimport android.app.NotificationManagerimport android.app.PendingIntentimport android.app.Serviceimport android.content.BroadcastReceiverimport android.content.Contextimport android.content.Intentimport android.content.IntentFilterimport android.os.Buildimport android.os.CountDownTimerimport android.os.IBinderimport androidx.core.app.NotificationCompat/** * NOUS — Timer Foreground Service (Module 14 v1.2 — Step 14.1, CRITICAL). * * REAL foreground service that keeps timers running in the background. * * ## What it does (per strategy v1.2 §"Architectural Shift 1") * * When a timer starts: * 1. TimerForegroundService starts as a foreground service * 2. Shows an ongoing notification: "⏱ Timer: 4:32 remaining" * 3. Updates the notification every 1 second (when screen is ON) * 4. Has a "Stop" action button * 5. Stops when timer fires or user stops * * ## Screen On/Off Optimization (per strategy v1.2 §"Polish 2") * * When screen turns OFF: * - Stop notification updates (save battery) * - Timer countdown continues in background * When screen turns ON: * - Resume notification updates * * @see <a href="docs/strategy/module-14-productivity-strategy-v1.2-final.md">§Shift 1 + Polish 2</a> */class TimerForegroundService : Service() {    companion object {        private const val TAG = "TimerFgService"        const val ACTION_START_TIMER = "com.roshan.persona.START_TIMER"        const val ACTION_STOP_TIMER = "com.roshan.persona.STOP_TIMER"        const val EXTRA_DURATION_MS = "duration_ms"        const val EXTRA_LABEL = "label"        const val NOTIFICATION_ID = 20001        const val CHANNEL_ID = "nous_timer_channel"        const val UPDATE_INTERVAL_MS = 1000L    }    private var countDownTimer: CountDownTimer? = null    private var remainingMs: Long = 0    private var label: String = "Timer"    private var screenOn: Boolean = true    private val screenReceiver = object : BroadcastReceiver() {        override fun onReceive(context: Context?, intent: Intent?) {            when (intent?.action) {                Intent.ACTION_SCREEN_OFF -> {                    screenOn = false                    Timber.tag(TAG).d("Screen OFF — pausing notification updates (timer continues).")                }                Intent.ACTION_SCREEN_ON -> {                    screenOn = true                    Timber.tag(TAG).d("Screen ON — resuming notification updates.")                    updateNotification(remainingMs)                }            }        }    }    override fun onCreate() {        super.onCreate()        createNotificationChannel()        // Register screen on/off receiver (REAL Android API).        val filter = IntentFilter().apply {            addAction(Intent.ACTION_SCREEN_OFF)            addAction(Intent.ACTION_SCREEN_ON)        }        registerReceiver(screenReceiver, filter)        Timber.tag(TAG).i("TimerForegroundService created.")    }    override fun onStartCommand(intent: Intent?, flags: Int, startId: Int): Int {        when (intent?.action) {            ACTION_START_TIMER -> {                val durationMs = intent.getLongExtra(EXTRA_DURATION_MS, 0)                label = intent.getStringExtra(EXTRA_LABEL) ?: "Timer"                remainingMs = durationMs                Timber.tag(TAG).i("Starting timer: $label (${durationMs / 1000}s).")                // Start as foreground service (REAL API).                startForeground(NOTIFICATION_ID, buildTimerNotification(remainingMs))                // Start countdown (REAL CountDownTimer).                startCountdown(durationMs)                return START_STICKY  // Restart if killed.            }            ACTION_STOP_TIMER -> {                Timber.tag(TAG).i("Stopping timer: $label.")                stopTimer()                return START_NOT_STICKY            }        }        return START_NOT_STICKY    }    /**     * Start the countdown timer (REAL CountDownTimer API).     */    private fun startCountdown(durationMs: Long) {        countDownTimer?.cancel()        countDownTimer = object : CountDownTimer(durationMs, UPDATE_INTERVAL_MS) {            override fun onTick(millisUntilFinished: Long) {                remainingMs = millisUntilFinished                // Only update notification when screen is ON (battery optimization).                if (screenOn) {                    updateNotification(millisUntilFinished)                }            }            override fun onFinish() {                Timber.tag(TAG).i("Timer finished: $label.")                onTimerComplete()            }        }.start()    }    /**     * Called when the timer reaches zero.     */    private fun onTimerComplete() {        // Show "Timer complete!" notification.        val notification = NotificationCompat.Builder(this, CHANNEL_ID)            .setSmallIcon(android.R.drawable.ic_menu_recent_history)            .setContentTitle("⏱ $label")            .setContentText("Timer complete!")            .setPriority(NotificationCompat.PRIORITY_HIGH)            .setAutoCancel(true)            .build()        val manager = getSystemService(NotificationManager::class.java)        manager.notify(NOTIFICATION_ID, notification)        // Stop the foreground service.        stopForeground(STOP_FOREGROUND_REMOVE)        stopSelf()    }    /**     * Stop the timer + service.     */    private fun stopTimer() {        countDownTimer?.cancel()        countDownTimer = null        stopForeground(STOP_FOREGROUND_REMOVE)        stopSelf()    }    /**     * Update the ongoing notification with remaining time.     */    private fun updateNotification(remaining: Long) {        val notification = buildTimerNotification(remaining)        val manager = getSystemService(NotificationManager::class.java)        manager.notify(NOTIFICATION_ID, notification)    }    /**     * Build the timer notification (REAL NotificationCompat).     */    private fun buildTimerNotification(remaining: Long): Notification {        val minutes = remaining / 60000        val seconds = (remaining % 60000) / 1000        val timeStr = String.format("%d:%02d", minutes, seconds)        // Stop action intent (FLAG_IMMUTABLE on API 31+).        val stopIntent = Intent(this, TimerForegroundService::class.java).apply {            action = ACTION_STOP_TIMER        }        val stopFlags = if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.M) {            PendingIntent.FLAG_UPDATE_CURRENT or PendingIntent.FLAG_IMMUTABLE        } else {            PendingIntent.FLAG_UPDATE_CURRENT        }        val stopPendingIntent = PendingIntent.getService(this, 0, stopIntent, stopFlags)        return NotificationCompat.Builder(this, CHANNEL_ID)            .setSmallIcon(android.R.drawable.ic_menu_recent_history)            .setContentTitle("⏱ $label")            .setContentText("$timeStr remaining")            .setPriority(NotificationCompat.PRIORITY_LOW)            .setOngoing(true)            .setOnlyAlertOnce(true)            .addAction(android.R.drawable.ic_media_pause, "Stop", stopPendingIntent)            .build()    }    /**     * Create the notification channel (REAL API 26+).     */    private fun createNotificationChannel() {        if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.O) {            val channel = NotificationChannel(                CHANNEL_ID,                "NOUS Timers",                NotificationManager.IMPORTANCE_LOW,            ).apply {                description = "Ongoing timer countdown notifications"                setShowBadge(false)            }            val manager = getSystemService(NotificationManager::class.java)            manager.createNotificationChannel(channel)        }    }    override fun onDestroy() {        super.onDestroy()        countDownTimer?.cancel()        unregisterReceiver(screenReceiver)        Timber.tag(TAG).i("TimerForegroundService destroyed.")    }    override fun onBind(intent: Intent?): IBinder? = null}
